/**
 * Synchronises the data shown by the site, at build time:
 *
 *   - every repository of the catalog (src/config/projects.ts): metadata,
 *     releases, recent commits, README, CHANGELOG and every Markdown document;
 *   - the Node-API reference, parsed from nodejs/node `doc/api/n-api.md`;
 *   - the Node-API ecosystem lists, parsed from nodejs/abi-stable-node.
 *
 * Output: src/generated/{projects,node-api,ecosystem}.json
 *
 * Sources and fallbacks, per field:
 *   1. GitHub REST API (uses GITHUB_TOKEN when set) and `git clone --depth`;
 *   2. the previously generated file (stale data beats no data);
 *   3. data/seed.json, a hand-written snapshot for the very first build.
 * A source that fails is logged as a warning; the build only fails when a
 * project would end up without a README.
 *
 *   npm run sync              # full synchronisation
 *   npm run sync -- --offline # validate the committed data, no network
 */
import { execFileSync } from "node:child_process"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"

import { PROJECTS, type ProjectConfig } from "../src/config/projects"
import {
  EcosystemFileSchema,
  NodeApiFileSchema,
  ProjectsFileSchema,
  type Commit,
  type EcosystemEntry,
  type EcosystemFile,
  type MediaEntry,
  type NodeApiFile,
  type NodeApiSection,
  type NodeApiSymbol,
  type ProjectData,
  type ProjectDoc,
  type ProjectsFile,
  type Release,
  type RepoMeta,
  type SymbolKind,
} from "../src/lib/data-schema"

const ROOT = path.resolve(import.meta.dirname, "..")
const OUT_DIR = path.join(ROOT, "src/generated")
const SEED_FILE = path.join(ROOT, "data/seed.json")
const OFFLINE = process.argv.includes("--offline")
const TOKEN = process.env.GITHUB_TOKEN ?? process.env.GH_TOKEN ?? ""
const NOW = new Date().toISOString()

const NODE_RAW = "https://raw.githubusercontent.com/nodejs/node/main"
// HEAD follows the default branch (currently `doc`).
const ABI_RAW = "https://raw.githubusercontent.com/nodejs/abi-stable-node/HEAD"
const NAPI_DOCS = "https://nodejs.org/docs/latest/api/n-api.html"

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

const warnings: string[] = []
function warn(message: string): void {
  warnings.push(message)
  console.warn(`  ! ${message}`)
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

async function fetchText(url: string, headers: Record<string, string> = {}): Promise<string> {
  const res = await fetch(url, { headers: { "user-agent": "napi-bindings-website", ...headers } })
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} for ${url}`)
  return res.text()
}

async function fetchJson<T>(url: string, headers: Record<string, string> = {}): Promise<T> {
  return JSON.parse(await fetchText(url, headers)) as T
}

async function github<T>(apiPath: string): Promise<T> {
  const headers: Record<string, string> = {
    accept: "application/vnd.github+json",
    "x-github-api-version": "2022-11-28",
  }
  const url = `https://api.github.com${apiPath}`
  if (!TOKEN) return fetchJson<T>(url, headers)
  try {
    return await fetchJson<T>(url, { ...headers, authorization: `Bearer ${TOKEN}` })
  } catch (error) {
    // An expired or foreign token must not hide public data.
    if (!errorMessage(error).startsWith("401")) throw error
    return fetchJson<T>(url, headers)
  }
}

async function attempt<T>(label: string, fn: () => Promise<T>): Promise<T | undefined> {
  try {
    return await fn()
  } catch (error) {
    warn(`${label}: ${errorMessage(error)}`)
    return undefined
  }
}

function readJson<T>(file: string): T | undefined {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8")) as T
  } catch {
    return undefined
  }
}

function writeJson(file: string, data: unknown): void {
  fs.mkdirSync(path.dirname(file), { recursive: true })
  fs.writeFileSync(file, `${JSON.stringify(data, null, 2)}\n`)
}

function git(cwd: string, ...args: string[]): string {
  return execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    env: { ...process.env, GIT_LFS_SKIP_SMUDGE: "1", GIT_TERMINAL_PROMPT: "0" },
    maxBuffer: 64 * 1024 * 1024,
  })
}

/** Anchor ids as generated by the Node.js documentation tooling. */
function nodeDocAnchor(text: string): string {
  return text
    .toLowerCase()
    .replace(/`/g, "")
    .trim()
    .replace(/[^a-z0-9_\- ]+/g, "")
    .replace(/\s+/g, "-")
}

/** Markdown inline syntax to plain text. */
function plainText(markdown: string): string {
  return markdown
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/\[([^\]]+)\]\[[^\]]*\]/g, "$1")
    .replace(/`|\*\*/g, "")
    .replace(/\s+/g, " ")
    .trim()
}

function firstSentences(text: string, max = 220): string {
  if (text.length <= max) return text
  const cut = text.slice(0, max)
  const end = Math.max(cut.lastIndexOf(". "), cut.lastIndexOf(". "))
  return end > 60 ? cut.slice(0, end + 1) : `${cut.replace(/\s+\S*$/, "")}…`
}

/* ------------------------------------------------------------------ */
/* Projects                                                            */
/* ------------------------------------------------------------------ */

type Seed = {
  repos: Record<string, { meta?: Partial<RepoMeta>; releases?: Omit<Release, "body">[] }>
}

type GhRepo = {
  description: string | null
  homepage: string | null
  language: string | null
  stargazers_count: number
  forks_count: number
  open_issues_count: number
  license: { spdx_id: string | null } | null
  topics?: string[]
  default_branch: string
  pushed_at: string | null
}

type GhRelease = {
  tag_name: string
  name: string | null
  published_at: string | null
  html_url: string
  prerelease: boolean
  draft: boolean
  body: string | null
}

const EMPTY_META: RepoMeta = {
  description: null,
  homepage: null,
  language: null,
  stars: null,
  forks: null,
  openIssues: null,
  license: null,
  topics: [],
  defaultBranch: "main",
  pushedAt: null,
}

const EXCLUDED_DOC = [
  /^README\.md$/i,
  /^CHANGELOG\.md$/i,
  /(^|\/)CODE_OF_CONDUCT\.md$/i,
  /(^|\/)LICENSE[^/]*\.md$/i,
  /^\.github\//,
  /(^|\/)node_modules\//,
]

type CloneResult = {
  defaultBranch: string
  commits: Commit[]
  readme: string
  changelog: string | null
  docs: ProjectDoc[]
}

function docSlug(file: string): string[] {
  const parts = file.replace(/\.md$/i, "").split("/")
  if (parts.at(-1)?.toLowerCase() === "readme") parts.pop()
  return parts.map((p) => p.toLowerCase())
}

/**
 * `docs/guide.md` is served at /docs/guide rather than /docs/docs/guide.
 * A shortened slug is only used when no other document claims it.
 */
function shortenDocSlugs(docs: ProjectDoc[]): void {
  const short = (doc: ProjectDoc): string[] => {
    if (doc.group !== "docs" && doc.group !== "doc") return doc.slug
    const rest = doc.slug.slice(1)
    return rest.length ? rest : ["overview"]
  }
  const counts = new Map<string, number>()
  for (const doc of docs) {
    for (const key of new Set([short(doc).join("/"), doc.slug.join("/")])) {
      counts.set(key, (counts.get(key) ?? 0) + 1)
    }
  }
  for (const doc of docs) {
    const candidate = short(doc)
    if (counts.get(candidate.join("/")) === 1) doc.slug = candidate
  }
}

function docTitle(file: string, markdown: string): string {
  const heading = /^#\s+(.+)$/m.exec(markdown)?.[1]
  if (heading) return plainText(heading)
  const base = path.basename(file, ".md")
  return base.toLowerCase() === "readme" ? path.dirname(file) : base.replace(/[-_]/g, " ")
}

function docOrder(doc: ProjectDoc): string {
  const rank = doc.group === "docs" || doc.group === "doc" ? "0" : doc.group === "" ? "2" : "1"
  const isIndex = doc.path.toLowerCase().endsWith("readme.md") ? "0" : "1"
  return `${rank}/${doc.group}/${doc.slug.length}/${isIndex}/${doc.path.toLowerCase()}`
}

function cloneRepository(config: ProjectConfig): CloneResult {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), `${config.slug}-`))
  try {
    git(dir, "clone", "--quiet", "--depth", "60", `https://github.com/${config.repo}.git`, ".")
    const defaultBranch = git(dir, "rev-parse", "--abbrev-ref", "HEAD").trim()

    const log = git(dir, "log", "-n", "40", "--format=%H%x1f%an%x1f%aI%x1f%s%x1e")
    const commits = log
      .split("\x1e")
      .map((r) => r.trim())
      .filter(Boolean)
      .map((record) => {
        const [sha = "", author = "", date = "", message = ""] = record.split("\x1f")
        return { sha, author, date, message, url: `https://github.com/${config.repo}/commit/${sha}` }
      })

    const read = (file: string): string | null => {
      const full = path.join(dir, file)
      return fs.existsSync(full) ? fs.readFileSync(full, "utf8") : null
    }

    const readme = read("README.md") ?? read("readme.md") ?? ""
    const changelog = read("CHANGELOG.md")

    const docs = git(dir, "ls-files", "*.md", "*.MD")
      .split("\n")
      .map((f) => f.trim())
      .filter((f) => f && !EXCLUDED_DOC.some((re) => re.test(f)))
      .map((file): ProjectDoc => {
        const markdown = read(file) ?? ""
        const group = file.includes("/") ? file.split("/")[0] ?? "" : ""
        return { path: file, slug: docSlug(file), title: docTitle(file, markdown), group, markdown }
      })
      .filter((doc) => doc.slug.length > 0 && doc.markdown.trim().length > 0)
      .sort((a, b) => docOrder(a).localeCompare(docOrder(b)))
    shortenDocSlugs(docs)

    return { defaultBranch, commits, readme, changelog, docs }
  } finally {
    try {
      fs.rmSync(dir, { recursive: true, force: true })
    } catch (error) {
      // A leftover temp directory must not hide the clone result or its error.
      warn(`${config.repo}: could not remove ${dir}: ${errorMessage(error)}`)
    }
  }
}

/** Section of a changelog that documents `tag`, used when a release has no notes. */
export function changelogSection(changelog: string | null, tag: string): string {
  if (!changelog) return ""
  const version = tag.replace(/^v/, "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
  const lines = changelog.split("\n")
  const start = lines.findIndex((l) => /^#{1,3}\s/.test(l) && new RegExp(`(^|[^\\d.])${version}([^\\d.]|$)`).test(l))
  if (start === -1) return ""
  const level = /^(#+)/.exec(lines[start] ?? "")?.[1]?.length ?? 2
  let end = lines.length
  for (let i = start + 1; i < lines.length; i++) {
    const m = /^(#+)\s/.exec(lines[i] ?? "")
    if (m?.[1] && m[1].length <= level) {
      end = i
      break
    }
  }
  return lines.slice(start + 1, end).join("\n").trim()
}

async function syncNpm(
  names: string[],
  previous: ProjectData | undefined
): Promise<ProjectData["npm"]> {
  return Promise.all(
    names.map(async (name) => {
      const prev = previous?.npm.find((p) => p.name === name)
      const encoded = name.replace("/", "%2f")
      const latest = await attempt(`npm ${name}`, () =>
        fetchJson<{ version: string }>(`https://registry.npmjs.org/${encoded}/latest`)
      )
      const downloads = await attempt(`npm downloads ${name}`, () =>
        fetchJson<{ downloads: number }>(`https://api.npmjs.org/downloads/point/last-week/${name}`)
      )
      return {
        name,
        version: latest?.version ?? prev?.version ?? null,
        weeklyDownloads: downloads?.downloads ?? prev?.weeklyDownloads ?? null,
      }
    })
  )
}

async function syncProject(
  config: ProjectConfig,
  previous: ProjectData | undefined,
  seed: Seed["repos"][string] | undefined
): Promise<ProjectData> {
  console.log(`- ${config.repo}`)

  const repo = await attempt(`${config.repo} metadata`, () => github<GhRepo>(`/repos/${config.repo}`))
  const meta: RepoMeta = repo
    ? {
        description: repo.description,
        homepage: repo.homepage || null,
        language: repo.language,
        stars: repo.stargazers_count,
        forks: repo.forks_count,
        openIssues: repo.open_issues_count,
        license: repo.license?.spdx_id ?? null,
        topics: repo.topics ?? [],
        defaultBranch: repo.default_branch,
        pushedAt: repo.pushed_at,
      }
    : { ...EMPTY_META, ...previous?.meta, ...(previous ? {} : seed?.meta) }

  const languages =
    (await attempt(`${config.repo} languages`, () =>
      github<Record<string, number>>(`/repos/${config.repo}/languages`)
    )) ?? previous?.languages ?? {}

  let content: CloneResult | undefined
  try {
    content = cloneRepository(config)
  } catch (error) {
    warn(`${config.repo} clone: ${errorMessage(error)}`)
  }

  const changelog = content ? content.changelog : (previous?.changelog ?? null)

  const ghReleases = await attempt(`${config.repo} releases`, () =>
    github<GhRelease[]>(`/repos/${config.repo}/releases?per_page=30`)
  )
  let releases: Release[]
  if (ghReleases) {
    releases = ghReleases
      .filter((r) => !r.draft)
      .map((r) => ({
        tag: r.tag_name,
        name: r.name || r.tag_name,
        publishedAt: r.published_at,
        url: r.html_url,
        prerelease: r.prerelease,
        body: r.body?.trim() ?? "",
      }))
  } else if (previous?.releases.length) {
    releases = previous.releases
  } else {
    releases = (seed?.releases ?? []).map((r) => ({ ...r, body: "" }))
  }
  releases = releases.map((r) => (r.body ? r : { ...r, body: changelogSection(changelog, r.tag) }))

  const npm = await syncNpm(config.npm ?? [], previous)

  const readme = content?.readme || previous?.readme || ""
  if (!readme) throw new Error(`${config.repo}: no README available from any source`)

  return {
    slug: config.slug,
    repo: config.repo,
    meta: { ...meta, defaultBranch: content?.defaultBranch ?? meta.defaultBranch },
    languages,
    releases,
    commits: content?.commits ?? previous?.commits ?? [],
    readme,
    changelog,
    docs: content?.docs ?? previous?.docs ?? [],
    npm,
    syncedAt: content ? NOW : (previous?.syncedAt ?? NOW),
  }
}

async function syncProjects(): Promise<void> {
  console.log("Projects")
  const file = path.join(OUT_DIR, "projects.json")
  const previous = readJson<ProjectsFile>(file)
  const seed = readJson<Seed>(SEED_FILE) ?? { repos: {} }

  const projects: ProjectData[] = []
  for (const config of PROJECTS) {
    const prev = previous?.projects.find((p) => p.slug === config.slug)
    projects.push(await syncProject(config, prev, seed.repos[config.slug]))
  }
  writeJson(file, ProjectsFileSchema.parse({ generatedAt: NOW, projects }))
}

/* ------------------------------------------------------------------ */
/* Node-API reference                                                  */
/* ------------------------------------------------------------------ */

type OpenSymbol = { name: string; level: number; group: string | null; lines: string[] }
type OpenSection = { id: string; title: string; lines: string[]; symbols: OpenSymbol[] }

const SYMBOL_HEADING = /^`([A-Za-z_][A-Za-z0-9_]*)`$/

function parseYaml(lines: string[]): { added: string[]; napiVersion: number | null; deprecated: boolean } {
  const start = lines.findIndex((l) => l.trim() === "<!-- YAML")
  if (start === -1) return { added: [], napiVersion: null, deprecated: false }
  const end = lines.findIndex((l, i) => i > start && l.trim() === "-->")
  const yaml = lines.slice(start + 1, end === -1 ? undefined : end)
  const added: string[] = []
  let napiVersion: number | null = null
  let deprecated = false
  for (let i = 0; i < yaml.length; i++) {
    const line = yaml[i] ?? ""
    const addedMatch = /^added:\s*(.*)$/.exec(line)
    if (addedMatch) {
      const inline = addedMatch[1]?.trim() ?? ""
      if (inline.startsWith("[")) {
        added.push(...inline.replace(/[[\]]/g, "").split(",").map((v) => v.trim()).filter(Boolean))
      } else if (inline) {
        added.push(inline)
      } else {
        for (let j = i + 1; j < yaml.length && /^\s+-\s/.test(yaml[j] ?? ""); j++) {
          added.push((yaml[j] ?? "").replace(/^\s+-\s*/, "").trim())
        }
      }
    }
    const napi = /^napiVersion:\s*(\d+)/.exec(line)
    if (napi?.[1]) napiVersion = Number(napi[1])
    if (/^deprecated:/.test(line)) deprecated = true
  }
  return { added, napiVersion, deprecated }
}

function stripYaml(lines: string[]): string[] {
  const out: string[] = []
  let inYaml = false
  for (const line of lines) {
    if (line.trim() === "<!-- YAML") inYaml = true
    else if (inYaml && line.trim() === "-->") inYaml = false
    else if (!inYaml) out.push(line)
  }
  return out
}

function resolveReferenceLinks(markdown: string, defs: Map<string, string>): string {
  return markdown.replace(
    /\[((?:[^[\]]|\[[^\]]*\])+)\]\[([^\]]*)\]/g,
    (all: string, text: string, label: string) => {
      const key = (label || text).toLowerCase().replace(/\s+/g, " ")
      const url = defs.get(key)
      return url ? `[${text}](${url})` : all
    }
  )
}

function symbolKind(name: string, group: string | null, signature: string | null): SymbolKind {
  if (/^[A-Z][A-Z0-9_]+$/.test(name)) return "macro"
  if (group && /callback types/i.test(group)) return "callback"
  if (!signature) return "type"
  if (/^\s*typedef\b/m.test(signature) || /^\s*(struct|enum)\b/m.test(signature)) return "type"
  return new RegExp(`\\b${name}\\s*\\(`).test(signature) ? "function" : "type"
}

function summarize(lines: string[]): string {
  const paragraphs = lines
    .join("\n")
    // The change history describes past behaviour, never what the API does.
    .replace(/^(?:\*\*)?Change History:?(?:\*\*)?[\s\S]*$/m, "")
    .replace(/```[\s\S]*?```/g, "")
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter(
      (p) =>
        p &&
        !p.startsWith("*") &&
        !p.startsWith("-") &&
        !p.startsWith(">") &&
        !p.startsWith("#") &&
        !p.startsWith("<") &&
        !p.startsWith("|") &&
        !/^Returns `napi_ok`/.test(p)
    )
  return firstSentences(plainText(paragraphs[0] ?? ""))
}

export function parseNodeApiDocs(md: string, headers: { js: string; node: string }): Omit<NodeApiFile, "generatedAt" | "source"> {
  const rawLines = md.split("\n")
  const defs = new Map<string, string>()
  const lines: string[] = []
  let fence = false
  for (const line of rawLines) {
    if (/^\s*```/.test(line)) fence = !fence
    const def = fence ? null : /^\[([^\]]+)\]:\s*(\S+)\s*$/.exec(line)
    if (def?.[1] && def[2]) defs.set(def[1].toLowerCase().replace(/\s+/g, " "), def[2])
    else lines.push(line)
  }

  const sections: OpenSection[] = [{ id: "introduction", title: "Introduction", lines: [], symbols: [] }]
  let section = sections[0] as OpenSection
  let symbol: OpenSymbol | null = null
  let group: string | null = null
  fence = false

  for (const line of lines) {
    if (/^\s*```/.test(line)) fence = !fence
    const heading = fence ? null : /^(#{1,4})\s+(.*?)\s*$/.exec(line)
    if (!heading?.[1] || heading[2] === undefined) {
      ;(symbol ? symbol.lines : section.lines).push(line)
      continue
    }
    const level = heading[1].length
    const text = heading[2]
    const symbolName = SYMBOL_HEADING.exec(text)?.[1]

    if (level === 1) continue
    if (level === 2) {
      symbol = null
      group = null
      section = { id: nodeDocAnchor(text), title: text, lines: [], symbols: [] }
      sections.push(section)
    } else if (symbolName && level >= 3) {
      symbol = { name: symbolName, level, group, lines: [] }
      section.symbols.push(symbol)
    } else if (symbol && level > symbol.level) {
      symbol.lines.push(line)
    } else {
      symbol = null
      if (level === 3) group = plainText(text)
      section.lines.push(line)
    }
  }

  const symbols: NodeApiSymbol[] = []
  const outSections: NodeApiSection[] = []
  const seen = new Set<string>()
  for (const s of sections) {
    for (const sym of s.symbols) {
      // The upstream file documents a few APIs twice (e.g. napi_is_error):
      // the first entry wins, later sections still list the symbol.
      if (seen.has(sym.name)) continue
      seen.add(sym.name)
      const yaml = parseYaml(sym.lines)
      const body = stripYaml(sym.lines)
      const text = body.join("\n")
      const signature = /```c\n([\s\S]*?)```/.exec(text)?.[1]?.trimEnd() ?? null
      // Only explicit markers: a missing napiVersion alone is not proof (some
      // stable entries simply omit it, the UI says "version not listed").
      const experimental =
        /Stability:\s*1\s*-\s*Experimental/i.test(text) ||
        (yaml.napiVersion === null && /NAPI_EXPERIMENTAL/.test(text))
      const deprecated = yaml.deprecated || /Stability:\s*0\s*-\s*Deprecated/i.test(text)
      const decl = new RegExp(`\\b${sym.name}\\b`)
      symbols.push({
        name: sym.name,
        anchor: sym.name.toLowerCase(),
        kind: symbolKind(sym.name, sym.group, signature),
        sectionId: s.id,
        section: s.title,
        group: sym.group,
        added: yaml.added,
        napiVersion: yaml.napiVersion,
        experimental,
        deprecated,
        header: decl.test(headers.js) ? "js_native_api.h" : decl.test(headers.node) ? "node_api.h" : null,
        signature,
        summary: summarize(body),
        markdown: resolveReferenceLinks(body.join("\n").trim(), defs),
      })
    }
    outSections.push({
      id: s.id,
      title: s.title,
      markdown: resolveReferenceLinks(s.lines.join("\n").trim(), defs),
      symbols: s.symbols.map((sym) => sym.name),
    })
  }

  const versionMatrix = [...md.matchAll(/<th scope="row">([^<]+)<\/th>\s*<td>([^<]+)<\/td>/g)].map((m) => ({
    version: (m[1] ?? "").trim(),
    supportedIn: (m[2] ?? "").trim(),
  }))

  return { versionMatrix, sections: outSections, symbols }
}

async function syncNodeApi(): Promise<void> {
  console.log("Node-API reference")
  const file = path.join(OUT_DIR, "node-api.json")
  const sourceUrl = `${NODE_RAW}/doc/api/n-api.md`
  const md = await attempt("n-api.md", () => fetchText(sourceUrl))
  const header = async (names: string[]): Promise<string> =>
    (await Promise.all(names.map((n) => fetchText(`${NODE_RAW}/src/${n}`)))).join("\n")
  const js = await attempt("js_native_api headers", () =>
    header(["js_native_api.h", "js_native_api_types.h"])
  )
  const node = await attempt("node_api headers", () => header(["node_api.h", "node_api_types.h"]))
  if (!md || js === undefined || node === undefined) {
    if (!fs.existsSync(file)) throw new Error("Node-API docs unavailable and no previous data")
    warn("keeping the previous Node-API reference")
    return
  }
  const parsed = parseNodeApiDocs(md, { js, node })
  console.log(`  ${parsed.sections.length} sections, ${parsed.symbols.length} symbols`)
  writeJson(
    file,
    NodeApiFileSchema.parse({
      generatedAt: NOW,
      source: { url: "https://github.com/nodejs/node/blob/main/doc/api/n-api.md", docsUrl: NAPI_DOCS },
      ...parsed,
    })
  )
}

/* ------------------------------------------------------------------ */
/* Ecosystem                                                           */
/* ------------------------------------------------------------------ */

function parseTables(md: string): EcosystemEntry[][] {
  const tables: EcosystemEntry[][] = []
  let current: EcosystemEntry[] | null = null
  for (const line of md.split("\n")) {
    const row = /^\|\s*\[([^\]]+)\]\(([^)]+)\)\s*\|\s*([^|]+?)\s*\|/.exec(line)
    if (row?.[1] && row[2] && row[3]) {
      if (!current) {
        current = []
        tables.push(current)
      }
      current.push({ name: row[1].trim(), url: row[2].trim(), language: row[3].trim(), project: null })
    } else if (!line.startsWith("|")) {
      current = null
    }
  }
  return tables
}

export function parseMedia(md: string): MediaEntry[] {
  const out: MediaEntry[] = []
  const re =
    /\*\*(.+?)\*\*<br\/>\s*\n(.+?)<br\/>\s*\n(.+?)\n[\s\S]*?src="([^"]+)"[\s\S]*?\]\((https?:[^)\s]+)\)/g
  for (const m of md.matchAll(re)) {
    out.push({
      title: (m[1] ?? "").trim(),
      speakers: (m[2] ?? "").trim(),
      date: (m[3] ?? "").trim(),
      thumbnail: m[4] ?? null,
      url: m[5] ?? "",
    })
  }
  return out
}

/** napi-bindings projects that belong in the upstream ecosystem lists. */
const OWN_ENTRIES: { list: "languages" | "runtimes"; entry: EcosystemEntry }[] = [
  {
    list: "languages",
    entry: { name: "napi-go", url: "https://github.com/napi-bindings/napi-go", language: "Go", project: "napi-go" },
  },
  {
    list: "runtimes",
    entry: {
      name: "quickjs-napi",
      url: "https://github.com/napi-bindings/quickjs-napi",
      language: "C",
      project: "quickjs-napi",
    },
  },
]

async function syncEcosystem(): Promise<void> {
  console.log("Ecosystem")
  const file = path.join(OUT_DIR, "ecosystem.json")
  const bindings = await attempt("node-api-engine-bindings.md", () =>
    fetchText(`${ABI_RAW}/node-api-engine-bindings.md`)
  )
  const media = await attempt("node-api-media.md", () => fetchText(`${ABI_RAW}/node-api-media.md`))
  if (!bindings || !media) {
    if (!fs.existsSync(file)) throw new Error("ecosystem lists unavailable and no previous data")
    warn("keeping the previous ecosystem lists")
    return
  }
  const [languages = [], experimentalLanguages = [], runtimes = []] = parseTables(bindings)
  const data: EcosystemFile = {
    generatedAt: NOW,
    languages,
    experimentalLanguages,
    runtimes,
    media: parseMedia(media),
  }
  for (const { list, entry } of OWN_ENTRIES) {
    if (!data[list].some((e) => e.url.toLowerCase() === entry.url.toLowerCase())) data[list].push(entry)
  }
  for (const list of [data.languages, data.experimentalLanguages, data.runtimes]) {
    for (const e of list) {
      const own = PROJECTS.find((p) => e.url.toLowerCase().endsWith(`/${p.repo.toLowerCase()}`))
      if (own) e.project = own.slug
    }
  }
  writeJson(file, EcosystemFileSchema.parse(data))
}

/* ------------------------------------------------------------------ */

async function main(): Promise<void> {
  if (OFFLINE) {
    ProjectsFileSchema.parse(readJson(path.join(OUT_DIR, "projects.json")))
    NodeApiFileSchema.parse(readJson(path.join(OUT_DIR, "node-api.json")))
    EcosystemFileSchema.parse(readJson(path.join(OUT_DIR, "ecosystem.json")))
    console.log("Offline: committed data is valid.")
    return
  }
  if (!TOKEN) console.log("GITHUB_TOKEN not set: GitHub API calls are unauthenticated (60 requests/hour).")
  await syncProjects()
  await syncNodeApi()
  await syncEcosystem()
  console.log(warnings.length ? `Done with ${warnings.length} warning(s).` : "Done.")
}

main().catch((error: unknown) => {
  console.error(error)
  process.exit(1)
})
